def records():
    output={}
    for line in ART.splitlines():
        dex,features,relation,contour,accent=line.split('|')
        assert dex not in output
        output[dex]={'exterior_features':features,'title_relation':relation,'contour':contour,'accent':accent}
    assert len(output)==94
    return output

DATA=records()

def render(row,color):
    item=DATA[row['dex']]
    source=f'<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="-1 -1 34 34" fill="none" stroke="#{color}" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="{item["contour"]}"/><path d="{item["accent"]}" stroke-width="1.6"/></svg>'
    return resvg_py.svg_to_bytes(svg_string=source)

if __name__=='__main__':
    rows=list(csv.DictReader((BASE/'catalog.tsv').open(encoding='utf-8'),delimiter='\t'))
    assert {row['dex'] for row in rows}==set(DATA)
    main(render_icon=render,output=OUT,style='species_outline_portrait',label='POKEMON PORTRAITS',poster_suffix='portraits')
    for row in rows:DATA[row['dex']].update(name=row['name'],title=row['title'])
    preview=json.loads((OUT/'preview-data.json').read_text(encoding='utf-8'))
    for item in preview:
        item['exterior_features']=DATA[item['dex']]['exterior_features'];item['title_relation']=DATA[item['dex']]['title_relation'];item['motif']=item['exterior_features']
    (OUT/'preview-data.json').write_text(json.dumps(preview,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
    (OUT/'design-rationale.json').write_text(json.dumps(DATA,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
